package br.com.studyou.data.repository

import br.com.studyou.domain.model.GeneratedGames
import java.util.concurrent.ConcurrentHashMap

/**
 * Holds the games generated by the backend for each uploaded file, keyed by the file's
 * client-side id. Shared between [FileRepositoryImpl] (which fills it in after a
 * successful upload) and [GameRepositoryImpl] (which reads from it) so games generated
 * alongside the upload are immediately available without a second backend round trip.
 */
class GeneratedGamesStore {
    private val games = ConcurrentHashMap<String, GeneratedGames>()

    fun put(fileId: String, generatedGames: GeneratedGames) {
        games[fileId] = generatedGames
    }

    fun get(fileId: String): GeneratedGames? = games[fileId]
}
